// Gift card page for the business demos, /demo/b/<slug>/gift/ (Ro, 27 Oct 2026), and the
// RealDays gift card, /gift-cards/ (G.kind "value", Ro, 8 Nov 2026): an amount to spend on
// any experience booked through RealDays. Both generated by tools/build-business-demos.mjs.
// The preview (G.sales 'off'): nothing is charged or sent, and the booking service never
// sees it. The gift card is kept in this browser (localStorage, th_gift_<code>) so the
// booking panel on the business's page can take its code.
// The real thing (Ro, 9 Nov 2026): the RealDays card is bought through the booking service
// (POST /gift-cards/checkout, then Stripe Checkout) and comes back here with ?order=.
// For everyone once G.sales is 'live'; before that, on the test service with ?gift_test=1
// (Stripe test card 4242 4242 4242 4242, nothing really charged).
(function () {
  var cfgEl = document.getElementById('gift-config');
  if (!cfgEl) return;
  var G = JSON.parse(cfgEl.textContent);
  var $ = function (id) { return document.getElementById(id); };
  var MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  var DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  var ERR_ICON = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="10"/><line x1="12" y1="7" x2="12" y2="13"/><line x1="12" y1="17" x2="12" y2="17"/></svg>';
  var VALUE = G.kind === 'value';
  var Q = new URLSearchParams(location.search);
  var ORDER = Q.get('order') || '';
  var TEST = VALUE && (Q.get('gift_test') === '1' || /^cs_test_/.test(ORDER));
  var REAL = VALUE && (G.sales === 'live' || TEST);
  var LOCAL = /^(localhost|127\.0\.0\.1)$/.test(location.hostname);
  var API = LOCAL ? 'http://127.0.0.1:8787' : TEST ? 'https://api-test.getrealdays.com' : 'https://api.getrealdays.com';
  var state = { opt: VALUE ? null : G.options[0], cents: VALUE ? G.amounts[G.default_index || 0] : 0, other: false, design: VALUE ? G.designs[0] : null, to: 'me', card: null };
  function price() { return VALUE ? state.cents : state.opt.price_cents; }

  function money(c) { return '$' + (c / 100).toLocaleString('en-AU', { minimumFractionDigits: c % 100 ? 2 : 0, maximumFractionDigits: 2 }); }
  function text(el, s) { el.textContent = s; return el; }
  // Visible placeholders: [TO CONFIRM ...] are marked, as on the business's page.
  function rich(el, s) {
    el.textContent = '';
    String(s || '').split(/(\[(?:TO CONFIRM|PERMISSION NEEDED)[^\]]*\])/).forEach(function (bit) {
      if (!bit) return;
      if (/^\[(TO CONFIRM|PERMISSION NEEDED)/.test(bit)) { var sp = document.createElement('span'); sp.className = 'tbc'; sp.textContent = bit; el.appendChild(sp); }
      else el.appendChild(document.createTextNode(bit));
    });
    return el;
  }
  // Dates as YYYY-MM-DD in the business's time zone, shown Australian style.
  function today() {
    try { return new Intl.DateTimeFormat('en-CA', { timeZone: G.timezone }).format(new Date()); } catch (e) { return new Date().toISOString().slice(0, 10); }
  }
  function addYears(d, n) { return (+d.slice(0, 4) + n) + d.slice(4); }
  function addDays(d, n) { return new Date(Date.UTC(+d.slice(0, 4), +d.slice(5, 7) - 1, +d.slice(8, 10)) + n * 864e5).toISOString().slice(0, 10); }
  function longDate(d) { return +d.slice(8, 10) + ' ' + MONTHS[+d.slice(5, 7) - 1] + ' ' + d.slice(0, 4); }
  function dayDate(d) { return DAYS[new Date(Date.UTC(+d.slice(0, 4), +d.slice(5, 7) - 1, +d.slice(8, 10))).getUTCDay()] + ' ' + +d.slice(8, 10) + ' ' + MONTHS[+d.slice(5, 7) - 1]; }
  function newCode() {
    var A = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789', out = '', r = new Uint32Array(8);
    if (window.crypto && crypto.getRandomValues) crypto.getRandomValues(r); else for (var i = 0; i < 8; i++) r[i] = Math.floor(Math.random() * 1e9);
    for (var j = 0; j < 8; j++) out += A[r[j] % A.length] + (j === 3 ? '-' : '');
    return G.prefix + '-' + out;
  }
  function what(o) { return VALUE ? money(state.cents) + ' RealDays gift card' : o.label.replace(/flight$/, '') + G.flight_name; }

  // ── Step 1: the flight (or the amount), how it's sent, and the card's words ──
  // The amount: one of G.amounts, or any whole dollar amount from G.min_cents to G.max_cents.
  function readOther() {
    var v = $('otherAmount').value.trim().replace(/[$,\s]/g, '');
    return /^\d+$/.test(v) ? +v * 100 : NaN;
  }
  function otherError() {
    var c = readOther();
    return !$('otherAmount').value.trim() ? 'Add an amount'
      : isNaN(c) ? 'Use whole dollars, like 120'
      : c < G.min_cents || c > G.max_cents ? 'Choose an amount from ' + money(G.min_cents) + ' to ' + money(G.max_cents)
      : '';
  }
  if (VALUE) [].forEach.call($('choices').querySelectorAll('.opt'), function (b) {
    b.onclick = function () {
      state.other = b.dataset.cents === 'other';
      [].forEach.call($('choices').children, function (x) { x.setAttribute('aria-pressed', x === b); });
      $('f-otherAmount').hidden = !state.other;
      setFieldError('otherAmount', '');
      if (state.other) { var c = readOther(); state.cents = isNaN(c) ? 0 : c; $('otherAmount').focus(); }
      else state.cents = +b.dataset.cents;
      preview(); total();
    };
  });
  // The card's design: one of G.designs, shown on the card as it's chosen.
  function designOf(key) { return G.designs.filter(function (d) { return d.key === key; })[0] || G.designs[0]; }
  function showDesign(d) {
    $('gcSrc').srcset = G.dir + d.key + '-800.avif';
    $('gcImg').src = G.dir + d.key + '-800.webp';
    $('gcImg').alt = d.alt;
    text($('gcCredit'), 'Photo: ' + d.credit);
  }
  if (VALUE) [].forEach.call($('designs').querySelectorAll('.gift-design'), function (b) {
    b.onclick = function () {
      state.design = designOf(b.dataset.design);
      [].forEach.call($('designs').children, function (x) { x.setAttribute('aria-pressed', x === b); });
      showDesign(state.design);
    };
  });
  if (VALUE) $('otherAmount').addEventListener('input', function () {
    setFieldError('otherAmount', '');
    var c = readOther(); state.cents = isNaN(c) ? 0 : c;
    preview(); total();
  });
  if (!VALUE) [].forEach.call($('choices').querySelectorAll('.opt'), function (b, i) {
    rich(b.lastChild, G.options[i].sub || money(G.options[i].price_cents));
    b.onclick = function () {
      state.opt = G.options[i];
      [].forEach.call($('choices').children, function (x) { x.setAttribute('aria-pressed', x === b); });
      preview(); total();
    };
  });
  [].forEach.call($('sendTo').querySelectorAll('.opt'), function (b) {
    b.onclick = function () {
      state.to = b.dataset.to;
      [].forEach.call($('sendTo').children, function (x) { x.setAttribute('aria-pressed', x === b); });
      $('themFields').hidden = state.to !== 'them';
      ['toEmail', 'sendOn'].forEach(function (id) { setFieldError(id, ''); });
    };
  });
  var t0 = today();
  $('sendOn').value = t0; $('sendOn').min = t0; $('sendOn').max = addDays(t0, 365);
  ['toName', 'fromName', 'message'].forEach(function (id) { $(id).addEventListener('input', function () { setFieldError(id, ''); preview(); }); });
  ['toEmail', 'sendOn', 'buyerName', 'buyerEmail'].forEach(function (id) { $(id).addEventListener('input', function () { setFieldError(id, ''); }); });
  $('message').addEventListener('input', function () { text($('msgCount'), $('message').value.length + ' / 200'); });

  function total() { $('totalValue').textContent = price() ? money(price()) : '-'; }
  // The card on the left follows what's typed.
  function preview(card) {
    var c = card || { label: what(state.opt), to: $('toName').value.trim(), from: $('fromName').value.trim(), message: $('message').value.trim(), code: '', valid_until: addYears(t0, G.valid_years) };
    text($('gcWhat'), VALUE && !card ? (state.cents ? money(state.cents) : '$') : VALUE ? money(c.value_cents) : c.label);
    text($('gcTo'), c.to || 'Their name');
    text($('gcFrom'), c.from || 'Your name');
    $('gcMsg').hidden = !c.message; text($('gcMsg'), c.message ? '“' + c.message + '”' : '');
    text($('gcCode'), c.code || 'Sent once bought');
    text($('gcUntil'), longDate(c.valid_until));
  }

  function setFieldError(id, msg) {
    var box = $('f-' + id), err = $(id + '-err');
    if (!box || !err) return;
    box.classList.toggle('has-error', !!msg);
    $(id).setAttribute('aria-invalid', msg ? 'true' : 'false');
    err.hidden = !msg;
    err.innerHTML = msg ? ERR_ICON + '<span></span>' : '';
    if (msg) err.lastChild.textContent = msg;
  }
  var EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
  function check(ids) {
    var first = null;
    ids.forEach(function (c) { setFieldError(c[0], c[1]); if (c[1] && !first) first = c[0]; });
    if (first) $(first).focus();
    return !first;
  }

  function step(n) {
    $('gStep1').hidden = n !== 1; $('gStep2').hidden = n !== 2;
    if (n === 2) $('buyerName').focus(); else $('giftCta').focus();
  }
  $('giftCta').onclick = function () {
    var them = state.to === 'them', on = $('sendOn').value;
    var ok = check([
      ['otherAmount', VALUE && state.other ? otherError() : ''],
      ['toName', $('toName').value.trim() ? '' : 'Add their name for the card'],
      ['toEmail', !them ? '' : !$('toEmail').value.trim() ? 'Add their email so we can send it' : EMAIL.test($('toEmail').value.trim()) ? '' : 'That email doesn\'t look right'],
      ['sendOn', !them ? '' : !on ? 'Choose a day to send it' : on < t0 ? 'Choose today or a later day' : on > addDays(t0, 365) ? 'Choose a day within a year' : ''],
      ['fromName', $('fromName').value.trim() ? '' : 'Add your name for the card']
    ]);
    if (!ok) return;
    text($('chosen'), what(state.opt) + (VALUE ? ', ' + state.design.label : '') + ' · ' + (them ? 'emailed to ' + $('toName').value.trim() + ', ' + dayDate(on) : 'emailed to you'));
    var rows = [[what(state.opt), money(price())], ['Valid until', longDate(addYears(t0, G.valid_years))]];
    $('summary').innerHTML = rows.map(function () { return '<div class="row"><span></span><span></span></div>'; }).join('') + '<div class="row"><b>Total</b><b></b></div>';
    rows.forEach(function (r, i) { text($('summary').children[i].children[0], r[0]); text($('summary').children[i].children[1], r[1]); });
    text($('summary').lastChild.lastChild, money(price()));
    step(2);
  };
  $('change').onclick = function () { step(1); };

  // ── Step 2: the buyer's details, then the card is "bought" ──
  $('gStep2').addEventListener('submit', function (e) {
    e.preventDefault();
    var ok = check([
      ['buyerName', $('buyerName').value.trim() ? '' : 'Add your name'],
      ['buyerEmail', !$('buyerEmail').value.trim() ? 'Add an email we can send your receipt to' : EMAIL.test($('buyerEmail').value.trim()) ? '' : 'That email doesn\'t look right']
    ]);
    if (!ok) return;
    var them = state.to === 'them';
    if (REAL) { buy(them); return; }
    var card = state.card = {
      code: newCode(), label: what(state.opt),
      ...(VALUE ? { kind: 'value', business: '*', value_cents: state.cents, balance_cents: state.cents, design: state.design.key }
        : { business: G.slug, experience: G.experience, option: state.opt.key, price_cents: state.opt.price_cents }),
      to: $('toName').value.trim(), to_email: them ? $('toEmail').value.trim() : '', send_on: them ? $('sendOn').value : t0,
      from: $('fromName').value.trim(), message: $('message').value.trim(), buyer_email: $('buyerEmail').value.trim(),
      bought: t0, valid_until: addYears(t0, G.valid_years), status: 'active'
    };
    try { localStorage.setItem('th_gift_' + card.code, JSON.stringify(card)); } catch (e2) {}
    done(card);
  });

  // ── The real thing: Stripe Checkout through the booking service ──
  var sending = false, idemKey = null, idemFor = '';
  function rid() {
    var a = new Uint8Array(16), s = '';
    if (window.crypto && crypto.getRandomValues) crypto.getRandomValues(a); else for (var i = 0; i < 16; i++) a[i] = Math.floor(Math.random() * 256);
    for (var j = 0; j < 16; j++) s += ('0' + a[j].toString(16)).slice(-2);
    return 'gc-' + s;
  }
  function showErr(msg) { var e = $('gErr'); if (!e) return; e.hidden = !msg; e.textContent = msg || ''; }
  function buy(them) {
    if (sending) return;
    var body = {
      amount_cents: state.cents, design: state.design.key,
      buyer_name: $('buyerName').value.trim(), buyer_email: $('buyerEmail').value.trim(),
      from_name: $('fromName').value.trim(), to_name: $('toName').value.trim(),
      send_to: them ? 'recipient' : 'buyer', message: $('message').value.trim() || null
    };
    if (them) { body.recipient_email = $('toEmail').value.trim(); body.send_on = $('sendOn').value; }
    // One card per order, however many times the button is pressed.
    var f = JSON.stringify(body);
    if (f !== idemFor) { idemFor = f; idemKey = rid(); }
    body.idempotency_key = idemKey;
    sending = true; showErr(''); $('requestBtn').textContent = 'Taking you to payment...';
    fetch(API + '/gift-cards/checkout', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) })
      .then(function (r) { return r.json().catch(function () { return {}; }).then(function (b) { return { status: r.status, body: b }; }); })
      .then(function (r) {
        if (r.body.checkout_url) { location.href = r.body.checkout_url; return; }
        sending = false; $('requestBtn').textContent = 'Pay by card';
        showErr(r.body.status === 'active' ? 'This gift card is already paid for. Check your email.' : r.body.message || 'Something went wrong. Please try again.');
      })
      .catch(function () { sending = false; $('requestBtn').textContent = 'Pay by card'; showErr('Payments are not available right now. Please try again in a moment.'); });
  }
  // Back from Stripe: the order, once the booking service has heard it's paid.
  function melDate(iso) { try { return new Intl.DateTimeFormat('en-CA', { timeZone: G.timezone }).format(new Date(iso)); } catch (e) { return iso.slice(0, 10); } }
  function loadOrder(tries) {
    fetch(API + '/gift-cards/order?session=' + encodeURIComponent(ORDER))
      .then(function (r) { return r.json().catch(function () { return {}; }).then(function (b) { return { status: r.status, body: b }; }); })
      .then(function (r) {
        var o = r.body;
        if (r.status === 200 && o.status === 'paid') return paid(o);
        if (r.status === 200 && o.status === 'pending' && tries < 12) { setTimeout(function () { loadOrder(tries + 1); }, 1500); return; }
        $('gForm').hidden = true; $('gDone').hidden = false;
        text($('doneLabel'), 'Gift card');
        text($('doneTitle'), o.status === 'pending' ? 'Payment received' : 'We can\'t find that order');
        text($('doneText'), o.status === 'pending' ? 'Thanks. Your gift card is on its way to your inbox. If it hasn\'t arrived in a few minutes, email rowena@getrealdays.com.' : 'If you paid, your gift card is in your inbox. Questions? Email rowena@getrealdays.com.');
        $('doneSummary').innerHTML = ''; $('giftDemoBox').hidden = true;
      })
      .catch(function () { if (tries < 12) setTimeout(function () { loadOrder(tries + 1); }, 1500); });
  }
  function paid(o) {
    var c = { code: o.code || '', label: money(o.amount_cents) + ' RealDays gift card', value_cents: o.amount_cents,
      to: o.to_name, to_email: o.send_to === 'recipient' ? o.recipient_email : '', send_on: o.send_on, from: o.from_name,
      message: o.message || '', buyer_email: o.buyer_email, valid_until: melDate(o.expires_at), sent: o.sent };
    if (o.design) { state.design = designOf(o.design); showDesign(state.design); }
    var them = !!c.to_email;
    $('gForm').hidden = true; $('gDone').hidden = false;
    text($('doneLabel'), c.code ? 'Gift card ' + c.code : 'Gift card');
    text($('doneTitle'), them ? 'It\'s on its way' : 'Your gift card is ready');
    text($('doneText'), them
      ? (c.sent ? 'We\'ve emailed it to ' + c.to + ' at ' + c.to_email + '.' : 'We\'ll email it to ' + c.to + ' at ' + c.to_email + ' on ' + dayDate(c.send_on) + '.') + ' Your receipt, with the code, is in your inbox.'
      : 'We\'ve emailed it to you at ' + c.buyer_email + ', ready to print or forward to ' + c.to + '.');
    var rows = [[c.label, money(c.value_cents)], ['Code', c.code || 'In ' + c.to + '\'s email, and your receipt'], ['Valid until', longDate(c.valid_until)]];
    $('doneSummary').innerHTML = rows.map(function () { return '<div class="row"><span></span><span></span></div>'; }).join('');
    rows.forEach(function (r, i) { text($('doneSummary').children[i].children[0], r[0]); text($('doneSummary').children[i].children[1], r[1]); });
    $('doneSummary').children[0].children[0].style.fontWeight = '600';
    $('giftDemoBox').hidden = true;
    preview({ label: c.label, value_cents: c.value_cents, to: c.to, from: c.from, message: c.message, code: c.code || 'Sent by email', valid_until: c.valid_until });
    $('book').scrollIntoView({ block: 'start' });
    $('doneTitle').focus({ preventScroll: true });
  }

  function done(c) {
    var them = !!c.to_email;
    $('gForm').hidden = true; $('gDone').hidden = false;
    text($('doneLabel'), 'Gift card ' + c.code);
    text($('doneTitle'), them ? 'It\'s on its way' : 'Your gift card is ready');
    text($('doneText'), them
      ? (c.send_on === t0 ? 'We\'ve emailed it to ' + c.to + ' at ' + c.to_email + '.' : 'We\'ll email it to ' + c.to + ' at ' + c.to_email + ' on ' + dayDate(c.send_on) + '.') + ' Your receipt and a copy of the gift card are in your inbox.'
      : 'We\'ve emailed it to you at ' + c.buyer_email + ', ready to print or forward to ' + c.to + '.');
    var rows = [[c.label, money(VALUE ? c.value_cents : c.price_cents)], ['Code', c.code], ['Valid until', longDate(c.valid_until)]];
    $('doneSummary').innerHTML = rows.map(function () { return '<div class="row"><span></span><span></span></div>'; }).join('');
    rows.forEach(function (r, i) { text($('doneSummary').children[i].children[0], r[0]); text($('doneSummary').children[i].children[1], r[1]); });
    $('doneSummary').children[0].children[0].style.fontWeight = '600';
    var book = VALUE ? G.book_url : G.book_url + '&gift=' + encodeURIComponent(c.code);
    $('redeemLink').href = book; $('emailBook').href = book;
    preview(c);
    // The email the person getting it opens.
    text($('emTo'), them ? c.to + ' <' + c.to_email + '>' : c.buyer_email + ' (to print or forward)');
    text($('emSubject'), c.from + ' has given you a ' + (VALUE ? c.label : c.label.toLowerCase()));
    text($('emHi'), 'Hi ' + c.to + ',');
    text($('emLead'), VALUE
      ? c.from + ' has given you a ' + c.label + '. Spend it on any experience booked through RealDays, any time before ' + longDate(c.valid_until) + '. Choose an experience, then add your code when you book.'
      : c.from + ' has given you a ' + c.label.toLowerCase() + ' with ' + G.business + '. Book a date that suits you, any time before ' + longDate(c.valid_until) + '.');
    $('emMsg').hidden = !c.message; text($('emMsg'), c.message);
    text($('emCode'), c.code);
    $('giftEmail').hidden = false;
    $('book').scrollIntoView({ block: 'start' });
    $('doneTitle').focus({ preventScroll: true });
  }
  $('seeEmail').onclick = function () { $('giftEmail').scrollIntoView({ behavior: 'smooth', block: 'start' }); };

  preview(); total();
  if (REAL) {
    $('requestBtn').textContent = 'Pay by card';
    if (TEST) {
      // Test mode, on the test booking service: say so plainly.
      if ($('giftStrip')) $('giftStrip').textContent = 'Test mode. Pay with Stripe\'s test card 4242 4242 4242 4242. Nothing is charged';
      if ($('giftFlag')) { $('giftFlag').firstChild.textContent = 'Test'; $('giftFlag').lastChild.textContent = 'Stripe test mode. Nothing is charged'; }
      var pay = document.querySelector('.steps li:nth-child(2) .prose');
      if (pay) pay.textContent = 'By card, on Stripe\'s secure page. In test mode, with Stripe\'s test card.';
      text($('buyUnder'), 'Test mode: you\'ll pay on Stripe\'s test page next, with card 4242 4242 4242 4242, any future date and any CVC.');
    }
    if (ORDER) loadOrder(0);
    else if (Q.get('result') === 'cancelled') showErr('Payment not finished, so nothing was charged. You can try again.');
  }
})();
